function validate([n]) {
  if (typeof n !== 'string' || n.length < 1 || n.length > 100000) return 'n needs 1 to 100000 digits.';
  if (!/^[0-9]+$/.test(n)) return 'n may contain digits only.';
  if (n[0] === '0') return 'n must be positive with no leading zeros.';
  return null;
}

