function minPartitions(n) {
  let largest = 0;
  for (const ch of n) {
    const digit = ch.charCodeAt(0) - 48;
    if (digit > largest) {
      largest = digit;
    }
    if (largest === 9) {
      break;
    }
  }
  return largest;
}

