function minPartitions(n) {
  // Simulate: each round subtracts the deci-binary number with a 1 under every nonzero digit.
  const digits = n.split('').map(Number);
  let rounds = 0;
  while (digits.some(d => d > 0)) {
    for (let i = 0; i < digits.length; i++) if (digits[i] > 0) digits[i]--;
    rounds++;
  }
  return rounds;
}

