function generate(rand, size) {
  const length = size === 'large' ? 10000 : 1 + Math.floor(rand() * 8);
  const top = 1 + Math.floor(rand() * 9);
  let s = String(1 + Math.floor(rand() * top));
  for (let i = 1; i < length; i++) s += String(Math.floor(rand() * (top + 1)));
  return [s];
}
